/* Native C chooser. Languages are discovered from validated data-pack directories. */
#include "catalog.h"
#include "storage.h"
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "../../../sdk/include/x1000/services/touch.h"
#include "../../../sdk/include/x1000/services/display.h"
#include "../../../sdk/include/x1000/services/stop.h"
#include "../../../sdk/include/x1000/services/font5x7.h"
#ifndef HB_BUILD_VERSION
#define HB_BUILD_VERSION "development"
#endif
static volatile int stopped;static struct hb_lp_catalog catalog;static unsigned short pixels[HB_DISPLAY_PIXELS];static char saved[33];static unsigned page;static const char*message="";
static void box(int x,int y,int w,int h,unsigned short c){for(int j=y;j<y+h&&j<432;j++)for(int i=x;i<x+w&&i<240;i++)if(i>=0&&j>=0)pixels[j*240+i]=c;}
static void text(int x,int y,const char*s,int scale,unsigned short color){for(;*s&&x+5*scale<=236;s++,x+=6*scale){unsigned c=(unsigned char)*s;if(c>='a'&&c<='z')c-=32;int g=c>='0'&&c<='9'?(int)c-'0':c>='A'&&c<='Z'?(int)c-'A'+10:-1;if(g>=0){for(int j=0;j<7;j++)for(int i=0;i<5;i++)if(glyph[g][j]&(1<<(4-i)))box(x+i*scale,y+j*scale,scale,scale,color);}else if(c=='-')box(x,y+3*scale,5*scale,scale,color);else if(c=='/')for(int i=0;i<5;i++)box(x+(4-i)*scale,y+i*scale,scale,scale,color);}}
static unsigned total(void){return catalog.count+1;}
static void scan(void){if(hb_language_saved_id(saved)||!saved[0])strcpy(saved,"stock");int status=hb_lp_catalog_scan(&catalog,&stopped);if(page*5>=total())page=0;message=status?"NO VERIFIED LANGUAGE PACKS":catalog.truncated?"LANGUAGE LIMIT REACHED":catalog.rejected?"INVALID PACKS WERE SKIPPED":"";if(strcmp(saved,"stock")){int found=0;for(unsigned i=0;i<catalog.count;i++)if(!strcmp(saved,catalog.entries[i].id))found=1;if(!found){strcpy(saved,"stock");message="SAVED PACK UNAVAILABLE";}}}
static void draw(void){box(0,0,240,432,0x0843);box(0,0,240,44,0x1a4b);text(12,14,"LANGUAGE",2,0xffff);for(unsigned row=0;row<5;row++){unsigned index=page*5+row;if(index>=total())break;const char*name=index<catalog.count?catalog.entries[index].name:"Original setting";const char*id=index<catalog.count?catalog.entries[index].id:"stock";int y=64+(int)row*52;box(8,y,224,44,!strcmp(saved,id)?0x2bca:0x1946);unsigned scale=strlen(name)<=17?2:1;text(18,y+(scale==2?15:18),name,(int)scale,0xffff);}text(8,338,total()>5?"SWIPE FOR MORE LANGUAGES":"TAP TITLE TO REFRESH",1,0x9cf3);text(8,354,"RETURN TO WALKMAN TO APPLY",1,0xffe0);text(8,370,message,1,0xffe0);if(total()>5){char b[16];snprintf(b,sizeof b,"%u/%u",page+1,(total()+4)/5);text(206,338,b,1,0x9cf3);}box(0,384,240,48,0x1a4b);text(18,402,"BACK TO APPS",2,0xffff);}
static int graphical(void){struct hb_devices d;int pressed=0,x=0,y=0,lastx=0,lasty=0;if(hb_stop_signals_install(&stopped))return 2;scan();if(stopped)return 0;draw();if(hb_devices_open(&d,pixels,HB_DISPLAY_PIXELS,&stopped))return stopped?0:2;hb_devices_present(&d);while(!stopped&&!d.failed){hb_devices_flush(&d);unsigned char packet[11];int got=hb_devices_next_touch(&d,packet,50);if(got<0){if(!stopped)d.failed=1;break;}if(!got)continue;struct hb_touch t;hb_touch_decode(packet,&t);if(t.down){if(!pressed){x=t.x;y=t.y;}pressed=1;lastx=t.x;lasty=t.y;continue;}if(!pressed)continue;pressed=0;if(!t.in_bounds)continue;int dx=lastx-x,dy=lasty-y;if(y>=384&&lasty>=384&&abs(dx)<=12&&abs(dy)<=12)break;if(y>=384)continue;if(abs(dy)>=40&&abs(dx)<=24){if(dy<0&&(page+1)*5<total())page++;else if(dy>0&&page)page--;draw();hb_devices_present(&d);continue;}if(abs(dx)>12||abs(dy)>12)continue;if(y<44){scan();draw();hb_devices_present(&d);continue;}if(y>=64&&y<324&&(y-64)%52<44){unsigned selected=page*5+(unsigned)(y-64)/52;if(selected<total()){const char*id=selected<catalog.count?catalog.entries[selected].id:"stock";if(selected<catalog.count&&!hb_lp_catalog_verify(id,&stopped))message="PACKAGE INVALID OR UNAVAILABLE";else if(!stopped){int status=hb_language_save_id(id);if(status>=0){strcpy(saved,id);message=status?"SAVED SYNC WARNING":"SAVED RETURN TO WALKMAN";}else message=status==-2?"STORAGE NOT VERIFIED":"SAVE FAILED";}draw();hb_devices_present(&d);}}}int bad=d.failed;if(hb_devices_close(&d)<0)bad=1;return stopped?0:bad?2:0;}
int main(int argc,char**argv){if(argc==1)return graphical();if(argc==2&&!strcmp(argv[1],"--help")){puts("Language: discover data packages in verified /contents/HOMEBREW/languages, save the selected ID externally, then return to Walkman. Requires generic external-loader firmware; candidate10 is incompatible. No firmware/database/NVP writes or automatic reboot. Swipe pages, tap title to refresh, BACK returns.");return 0;}if(argc==2&&!strcmp(argv[1],"--version")){puts(HB_BUILD_VERSION);return 0;}if(argc==2&&!strcmp(argv[1],"--selftest")){char id[33];return hb_lp_id("zh-CN")&&hb_lp_choice("en\n",3,id)&&!strcmp(id,"en")&&!hb_lp_id("../en")?0:1;}if(argc==2&&!strcmp(argv[1],"--catalog")){scan();for(unsigned i=0;i<catalog.count;i++)printf("%s\t%s\t%s\n",catalog.entries[i].id,catalog.entries[i].base,catalog.entries[i].name);return catalog.storage_unavailable?1:0;}return 64;}
